import React, { useEffect, useMemo, useState } from "react";
import {
  factionAPI,
  npcAPI,
  progressClockAPI,
  resolveMediaUrl,
} from "../../features/character-sheet";
import { buildRouteHref, handleSpaNavClick } from "../../utils/spaNavigation";
import AvatarCropModal from "../AvatarCropModal";
import ConfirmDeleteModal from "../ConfirmDeleteModal";

const TIER_OPTIONS = [0, 1, 2, 3, 4, 5, 6];
const TIER_LABEL = ["—", "I", "II", "III", "IV", "V", "VI"];

const CLOCK_TYPE_OPTIONS = [
  { value: "CUSTOM", label: "Custom" },
  { value: "DANGER", label: "Danger" },
  { value: "MISSION", label: "Mission" },
  { value: "PROJECT", label: "Long-term Project" },
  { value: "COUNTDOWN", label: "Countdown" },
];

const CLOCK_SEGMENT_OPTIONS = [4, 6, 8, 10, 12];

/**
 * Compact inline editor for a faction. Lives inside the dark Home page
 * "Your Factions" list — clicking an f-card opens this beneath the card.
 * Renders name/type/tier/hold/rep/visibility/notes, NPC roster, and faction
 * clocks without leaving the home page.
 */
const HomeFactionInlineEditor = ({
  faction,
  campaign,
  onCancel,
  onSaved,
  onDeleted,
  onNavigateToNPC,
}) => {
  const [form, setForm] = useState({
    name: faction.name || "",
    faction_type: faction.faction_type || "",
    level: Number(faction.level) || 0,
    hold: faction.hold === "strong" ? "strong" : "weak",
    reputation: Number(faction.reputation) || 0,
    visible_to_players: faction.visible_to_players !== false,
    players_see_tier: faction.players_see_tier !== false,
    players_see_hold: faction.players_see_hold !== false,
    players_see_reputation: faction.players_see_reputation !== false,
    players_see_notes: faction.players_see_notes !== false,
    players_see_npcs: faction.players_see_npcs !== false,
    players_see_identity: faction.players_see_identity !== false,
    players_see_inventory: faction.players_see_inventory !== false,
    players_see_contacts: faction.players_see_contacts !== false,
    players_see_faction_status: faction.players_see_faction_status !== false,
    notes: faction.notes || "",
  });
  const [imageFile, setImageFile] = useState(null);
  const [imageUrlDraft, setImageUrlDraft] = useState(
    () => String(faction.image_url || "").trim(),
  );
  const [clearImage, setClearImage] = useState(false);
  const [cropOpen, setCropOpen] = useState(false);
  const [previewError, setPreviewError] = useState(false);
  const [npcList, setNpcList] = useState(
    Array.isArray(faction.npcs) ? faction.npcs : [],
  );
  const [addNpcId, setAddNpcId] = useState("");
  const [clocks, setClocks] = useState([]);
  const [clocksLoading, setClocksLoading] = useState(true);
  const [showNewClock, setShowNewClock] = useState(false);
  const [newClockName, setNewClockName] = useState("");
  const [newClockSegments, setNewClockSegments] = useState(4);
  const [newClockType, setNewClockType] = useState("CUSTOM");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [deleteBusy, setDeleteBusy] = useState(false);

  const blobPreview = useMemo(() => {
    if (!imageFile) return null;
    return URL.createObjectURL(imageFile);
  }, [imageFile]);

  useEffect(() => {
    if (!blobPreview) return undefined;
    return () => URL.revokeObjectURL(blobPreview);
  }, [blobPreview]);

  const imagePreview =
    blobPreview ||
    (!clearImage
      ? resolveMediaUrl(
          (String(imageUrlDraft || "").trim()
            ? imageUrlDraft
            : faction.image || faction.image_url) || "",
        ) || null
      : null);

  useEffect(() => {
    setPreviewError(false);
  }, [imagePreview]);

  useEffect(() => {
    let cancelled = false;
    setClocksLoading(true);
    const params = campaign?.id ? { campaign: campaign.id } : {};
    progressClockAPI
      .getProgressClocks(params)
      .then((list) => {
        if (cancelled) return;
        const filtered = (Array.isArray(list) ? list : []).filter(
          (c) => c.faction === faction.id,
        );
        setClocks(filtered);
      })
      .catch(() => {
        if (!cancelled) setClocks([]);
      })
      .finally(() => {
        if (!cancelled) setClocksLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [faction.id, campaign?.id]);

  const campaignNpcs = Array.isArray(campaign?.campaign_npcs)
    ? campaign.campaign_npcs
    : [];
  const unaffiliatedNpcs = campaignNpcs.filter(
    (n) => !npcList.some((existing) => existing.id === n.id),
  );

  const handlePickImage = (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setClearImage(false);
    setImageUrlDraft("");
    setImageFile(file);
    setPreviewError(false);
  };

  const handleClearImage = () => {
    setImageFile(null);
    setImageUrlDraft("");
    setClearImage(true);
    setCropOpen(false);
    setPreviewError(false);
  };

  const handleCropApply = (file) => {
    setClearImage(false);
    setImageUrlDraft("");
    setImageFile(file);
    setPreviewError(false);
    setCropOpen(false);
  };

  const handleImageUrlChange = (e) => {
    const next = e.target.value;
    setImageUrlDraft(next);
    setImageFile(null);
    setClearImage(false);
    setPreviewError(false);
  };

  const handleSave = async () => {
    setError(null);
    if (!form.name.trim()) {
      setError("Name is required.");
      return;
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        faction_type: form.faction_type || "",
        level: Number(form.level) || 0,
        hold: form.hold === "strong" ? "strong" : "weak",
        reputation: Number(form.reputation) || 0,
        visible_to_players: !!form.visible_to_players,
        players_see_tier: form.players_see_tier !== false,
        players_see_hold: form.players_see_hold !== false,
        players_see_reputation: form.players_see_reputation !== false,
        players_see_notes: form.players_see_notes !== false,
        players_see_npcs: form.players_see_npcs !== false,
        players_see_identity: form.players_see_identity !== false,
        players_see_inventory: form.players_see_inventory !== false,
        players_see_contacts: form.players_see_contacts !== false,
        players_see_faction_status: form.players_see_faction_status !== false,
        notes: form.notes || "",
      };
      if (imageFile) {
        payload.imageFile = imageFile;
        payload.image_url = "";
      } else if (clearImage) {
        payload.image = null;
        payload.image_url = "";
      } else {
        const url = String(imageUrlDraft || "").trim();
        const prev = String(faction.image_url || "").trim();
        if (url !== prev || (url && faction.image)) {
          payload.image_url = url;
        }
      }
      const updated = await factionAPI.patchFaction(faction.id, payload);
      onSaved?.({ ...updated, npcs: npcList });
    } catch (e) {
      setError(e.message || "Could not save.");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = () => {
    setDeleteConfirmOpen(true);
  };

  const handleConfirmDelete = async () => {
    setError(null);
    setDeleteBusy(true);
    try {
      await factionAPI.deleteFaction(faction.id);
      setDeleteConfirmOpen(false);
      onDeleted?.(faction.id);
    } catch (e) {
      setError(e.message || "Could not delete.");
    } finally {
      setDeleteBusy(false);
    }
  };

  const handleAddNpc = async () => {
    if (!addNpcId) return;
    const npcId = Number(addNpcId);
    const npc = campaignNpcs.find((n) => n.id === npcId);
    setError(null);
    try {
      await npcAPI.patchNPC(npcId, { faction: faction.id });
      setNpcList((prev) => {
        if (prev.some((n) => n.id === npcId)) return prev;
        return [...prev, npc || { id: npcId, name: `NPC ${npcId}` }];
      });
      setAddNpcId("");
    } catch (e) {
      setError(e.message || "Could not attach NPC.");
    }
  };

  const handleRemoveNpc = async (npcId) => {
    setError(null);
    try {
      await npcAPI.patchNPC(npcId, { faction: null });
      setNpcList((prev) => prev.filter((n) => n.id !== npcId));
    } catch (e) {
      setError(e.message || "Could not detach NPC.");
    }
  };

  const updateClockLocal = (id, patch) =>
    setClocks((prev) => prev.map((c) => (c.id === id ? { ...c, ...patch } : c)));

  const tickClock = async (clk, delta) => {
    const next = Math.max(
      0,
      Math.min(clk.max_segments, (clk.filled_segments || 0) + delta),
    );
    if (next === clk.filled_segments) return;
    updateClockLocal(clk.id, { filled_segments: next });
    try {
      await progressClockAPI.updateProgressClock(clk.id, {
        filled_segments: next,
      });
    } catch (e) {
      setError(e.message || "Could not update clock.");
    }
  };

  const toggleClockVisible = async (clk, visible) => {
    updateClockLocal(clk.id, { visible_to_players: visible });
    try {
      await progressClockAPI.updateProgressClock(clk.id, {
        visible_to_players: visible,
      });
    } catch (e) {
      setError(e.message || "Could not update clock visibility.");
    }
  };

  const deleteClock = async (clkId) => {
    if (!window.confirm("Delete this clock?")) return;
    try {
      await progressClockAPI.deleteProgressClock(clkId);
      setClocks((prev) => prev.filter((c) => c.id !== clkId));
    } catch (e) {
      setError(e.message || "Could not delete clock.");
    }
  };

  const createClock = async () => {
    if (!newClockName.trim()) return;
    try {
      const created = await progressClockAPI.createProgressClock({
        campaign: campaign?.id,
        faction: faction.id,
        name: newClockName.trim(),
        clock_type: newClockType,
        max_segments: newClockSegments,
      });
      setClocks((prev) => [...prev, created]);
      setNewClockName("");
      setNewClockSegments(4);
      setNewClockType("CUSTOM");
      setShowNewClock(false);
    } catch (e) {
      setError(e.message || "Could not create clock.");
    }
  };

  return (
    <div className="f-edit-panel" onClick={(e) => e.stopPropagation()}>
      {error && <div className="f-edit-error">{error}</div>}

      <div className="f-edit-photo">
        {imagePreview && !previewError ? (
          <img
            className="f-edit-photo-preview"
            src={imagePreview}
            alt=""
            crossOrigin="anonymous"
            onError={() => setPreviewError(true)}
            onLoad={() => setPreviewError(false)}
          />
        ) : (
          <div className="f-edit-photo-empty" aria-hidden="true">
            {(form.name || "F").trim().charAt(0).toUpperCase()}
          </div>
        )}
        <div className="f-edit-photo-actions">
          <label className="f-edit-photo-btn">
            Upload photo
            <input
              type="file"
              accept="image/jpeg,image/png,image/webp,image/gif"
              hidden
              onChange={handlePickImage}
            />
          </label>
          <button
            type="button"
            className="f-edit-photo-btn"
            disabled={!imagePreview || previewError}
            onClick={() => setCropOpen(true)}
          >
            Crop
          </button>
          <button
            type="button"
            className="f-edit-photo-btn f-edit-photo-btn-clear"
            disabled={!imagePreview && !clearImage && !imageUrlDraft}
            onClick={handleClearImage}
          >
            Clear
          </button>
        </div>
        <label className="f-edit-field f-edit-field-wide f-edit-photo-url">
          <span>Image URL</span>
          <input
            type="url"
            inputMode="url"
            placeholder="https://…"
            value={imageUrlDraft}
            onChange={handleImageUrlChange}
            disabled={Boolean(imageFile)}
          />
        </label>
        {cropOpen && imagePreview && !previewError ? (
          <AvatarCropModal
            imageSrc={imagePreview}
            onCancel={() => setCropOpen(false)}
            onApply={handleCropApply}
          />
        ) : null}
      </div>

      <div className="f-edit-grid">
        <label className="f-edit-field f-edit-field-wide">
          <span>Name</span>
          <input
            type="text"
            value={form.name}
            onChange={(e) =>
              setForm((p) => ({ ...p, name: e.target.value }))
            }
          />
        </label>
        <label className="f-edit-field f-edit-field-wide">
          <span>Type</span>
          <input
            type="text"
            value={form.faction_type}
            placeholder="e.g. Criminal Syndicate"
            onChange={(e) =>
              setForm((p) => ({ ...p, faction_type: e.target.value }))
            }
          />
        </label>
        <label className="f-edit-field">
          <span>Tier</span>
          <select
            value={form.level}
            onChange={(e) =>
              setForm((p) => ({ ...p, level: Number(e.target.value) }))
            }
          >
            {TIER_OPTIONS.map((n) => (
              <option key={n} value={n}>
                {TIER_LABEL[n]}
              </option>
            ))}
          </select>
        </label>
        <label className="f-edit-field">
          <span>Hold</span>
          <select
            value={form.hold}
            onChange={(e) =>
              setForm((p) => ({ ...p, hold: e.target.value }))
            }
          >
            <option value="weak">Weak</option>
            <option value="strong">Strong</option>
          </select>
        </label>
        <label className="f-edit-field">
          <span>Rep w/ crew</span>
          <input
            type="number"
            min={-3}
            max={3}
            value={form.reputation}
            onChange={(e) =>
              setForm((p) => ({
                ...p,
                reputation: parseInt(e.target.value, 10) || 0,
              }))
            }
          />
        </label>
        <label className="f-edit-field f-edit-field-checkbox">
          <input
            type="checkbox"
            checked={form.visible_to_players}
            onChange={(e) =>
              setForm((p) => ({
                ...p,
                visible_to_players: e.target.checked,
              }))
            }
          />
          <span>Visible to players</span>
        </label>
      </div>

      <div className="f-edit-section">
        <div className="f-edit-section-label">Players may also see</div>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "8px 14px",
            opacity: form.visible_to_players ? 1 : 0.5,
          }}
        >
          {[
            ["players_see_tier", "Tier"],
            ["players_see_hold", "Hold"],
            ["players_see_reputation", "Reputation"],
            ["players_see_notes", "Notes"],
            ["players_see_npcs", "NPCs"],
            ["players_see_identity", "Identity"],
            ["players_see_inventory", "Inventory"],
            ["players_see_contacts", "Contacts"],
            ["players_see_faction_status", "Faction rep"],
          ].map(([key, label]) => (
            <label key={key} className="f-edit-field f-edit-field-checkbox">
              <input
                type="checkbox"
                disabled={!form.visible_to_players}
                checked={form[key] !== false}
                onChange={(e) =>
                  setForm((p) => ({
                    ...p,
                    [key]: e.target.checked,
                  }))
                }
              />
              <span>{label}</span>
            </label>
          ))}
        </div>
      </div>

      <label className="f-edit-field f-edit-field-wide f-edit-field-notes">
        <span>Notes</span>
        <textarea
          rows={3}
          value={form.notes}
          onChange={(e) =>
            setForm((p) => ({ ...p, notes: e.target.value }))
          }
        />
      </label>

      <div className="f-edit-section">
        <div className="f-edit-section-label">NPC Members</div>
        {npcList.length === 0 ? (
          <div className="f-edit-empty">No NPCs in this faction.</div>
        ) : (
          <ul className="f-edit-npc-list">
            {npcList.map((n) => {
              const label = n.name || n.stand_name || `NPC ${n.id}`;
              return (
              <li key={n.id} className="f-edit-npc-row">
                {typeof onNavigateToNPC === "function" && n.id != null ? (
                  <a
                    className="f-edit-npc-name f-edit-npc-name-link"
                    href={buildRouteHref("npcs", { npcId: n.id })}
                    onClick={(e) =>
                      handleSpaNavClick(e, () => onNavigateToNPC(n.id))
                    }
                  >
                    {label}
                  </a>
                ) : (
                  <span className="f-edit-npc-name">{label}</span>
                )}
                <button
                  type="button"
                  className="f-card-btn f-card-btn-delete"
                  onClick={() => handleRemoveNpc(n.id)}
                >
                  Remove
                </button>
              </li>
              );
            })}
          </ul>
        )}
        {unaffiliatedNpcs.length > 0 && (
          <div className="f-edit-npc-add">
            <select
              value={addNpcId}
              onChange={(e) => setAddNpcId(e.target.value)}
            >
              <option value="">Add an NPC…</option>
              {unaffiliatedNpcs.map((n) => (
                <option key={n.id} value={n.id}>
                  {n.name || n.stand_name || `NPC ${n.id}`}
                </option>
              ))}
            </select>
            <button
              type="button"
              className="f-card-btn"
              onClick={handleAddNpc}
              disabled={!addNpcId}
            >
              Add
            </button>
          </div>
        )}
      </div>

      <div className="f-edit-section">
        <div className="f-edit-section-label">Clocks</div>
        {clocksLoading ? (
          <div className="f-edit-empty">Loading clocks…</div>
        ) : clocks.length === 0 ? (
          <div className="f-edit-empty">No clocks yet.</div>
        ) : (
          <ul className="f-edit-clock-list">
            {clocks.map((clk) => (
              <li key={clk.id} className="f-edit-clock-row">
                <span className="f-edit-clock-name">{clk.name}</span>
                <span className="f-edit-clock-count">
                  {clk.filled_segments}/{clk.max_segments}
                </span>
                <button
                  type="button"
                  className="f-card-btn"
                  onClick={() => tickClock(clk, -1)}
                  aria-label="Decrement clock"
                >
                  −
                </button>
                <button
                  type="button"
                  className="f-card-btn"
                  onClick={() => tickClock(clk, 1)}
                  aria-label="Increment clock"
                >
                  +
                </button>
                <label className="f-edit-clock-vis">
                  <input
                    type="checkbox"
                    checked={!!clk.visible_to_players}
                    onChange={(e) =>
                      toggleClockVisible(clk, e.target.checked)
                    }
                  />
                  <span>visible</span>
                </label>
                <button
                  type="button"
                  className="f-card-btn f-card-btn-delete"
                  onClick={() => deleteClock(clk.id)}
                  aria-label="Delete clock"
                >
                  ×
                </button>
              </li>
            ))}
          </ul>
        )}
        {showNewClock ? (
          <div className="f-edit-clock-create">
            <input
              type="text"
              placeholder="Clock name"
              value={newClockName}
              onChange={(e) => setNewClockName(e.target.value)}
            />
            <select
              value={newClockSegments}
              onChange={(e) =>
                setNewClockSegments(parseInt(e.target.value, 10))
              }
              aria-label="Segments"
            >
              {CLOCK_SEGMENT_OPTIONS.map((n) => (
                <option key={n} value={n}>
                  {n} seg
                </option>
              ))}
            </select>
            <select
              value={newClockType}
              onChange={(e) => setNewClockType(e.target.value)}
              aria-label="Clock type"
            >
              {CLOCK_TYPE_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              className="f-card-btn"
              onClick={createClock}
              disabled={!newClockName.trim()}
            >
              Create
            </button>
            <button
              type="button"
              className="f-card-btn"
              onClick={() => {
                setShowNewClock(false);
                setNewClockName("");
              }}
            >
              Cancel
            </button>
          </div>
        ) : (
          <button
            type="button"
            className="f-card-btn"
            onClick={() => setShowNewClock(true)}
          >
            + New Clock
          </button>
        )}
      </div>

      <div className="f-edit-actions">
        <button
          type="button"
          className="f-card-btn f-card-btn-primary"
          onClick={handleSave}
          disabled={saving}
        >
          {saving ? "Saving…" : "Save"}
        </button>
        <button
          type="button"
          className="f-card-btn"
          onClick={onCancel}
          disabled={saving}
        >
          Cancel
        </button>
        <button
          type="button"
          className="f-card-btn f-card-btn-delete"
          onClick={handleDelete}
          disabled={saving || deleteBusy}
        >
          Delete Faction
        </button>
      </div>
      <ConfirmDeleteModal
        open={deleteConfirmOpen}
        message={`Delete faction “${faction.name || "this faction"}”?`}
        busy={deleteBusy}
        onCancel={() => {
          if (!deleteBusy) setDeleteConfirmOpen(false);
        }}
        onConfirm={handleConfirmDelete}
      />
    </div>
  );
};

export default HomeFactionInlineEditor;
